"""Regression tests for bugs found in code review (not ports of Java tests)."""

import pytest

from commands3._common.api import Canceled, Command, RobotMode
from commands3._frontends.asyncgen import Coroutine, co

from .helpers import DummyMechanism, Ref


def _parked(name):
    async def body():
        await co.park()

    return Command.no_requirements(body).named(name)


def test_cleanup_error_during_cancel_still_cancels_children_and_runs_hooks(scheduler, events):
    child = _parked("Child")
    exited = Ref(False)
    canceled = Ref(False)

    async def parent_body():
        try:
            co.fork(child)
            await co.park()
        finally:
            raise ValueError("cleanup failed")

    parent = (Command.no_requirements(parent_body)
              .when_exited(lambda: exited.set(True))
              .when_canceled(lambda: canceled.set(True))
              .named("Parent"))
    scheduler.schedule(parent)
    scheduler.run()
    assert scheduler.is_running(child)

    with pytest.raises(ValueError, match="cleanup failed"):
        scheduler.cancel(parent)
    assert not scheduler.is_running(parent)
    assert not scheduler.is_running(child), "child must not be orphaned"
    assert exited.get() and canceled.get()
    assert any(isinstance(e, Canceled) and e.command is parent for e in events)

    scheduler.run()
    assert not scheduler.is_running(child)


def test_cleanup_error_during_cancel_all_still_cancels_everything(scheduler):
    async def bad_body():
        try:
            await co.park()
        finally:
            raise ValueError("cleanup failed")

    bad = Command.no_requirements(bad_body).named("Bad")
    others = [_parked(f"Other {i}") for i in range(3)]
    scheduler.schedule(bad)
    for c in others:
        scheduler.schedule(c)
    scheduler.run()

    with pytest.raises(ValueError, match="cleanup failed"):
        scheduler.cancel_all()
    assert not scheduler.is_running(bad)
    for c in others:
        assert not scheduler.is_running(c)


def test_cancel_all_inside_a_command_stops_its_body(scheduler):
    child = _parked("Child")
    after = Ref(False)

    async def parent_body():
        scheduler.cancel_all()
        after.set(True)
        co.fork(child)
        yield

    parent = Command.no_requirements(parent_body).named("Parent")
    scheduler.schedule(parent)
    for _ in range(3):
        scheduler.run()
    assert not after.get(), "the body must not continue past cancel_all()"
    assert not scheduler.is_running(parent)
    assert not scheduler.is_running(child)


def test_on_exit_runs_when_the_body_raises(scheduler):
    mechanism = DummyMechanism("mechanism", scheduler)
    exited = Ref(False)

    async def bad():
        yield
        raise ValueError("boom")

    cmd = mechanism.run(bad).when_exited(lambda: exited.set(True)).named("Bad")
    scheduler.schedule(cmd)
    scheduler.run()
    with pytest.raises(ValueError, match="boom"):
        scheduler.run()
    assert exited.get()
    assert not scheduler.is_running(cmd)


def test_stale_binding_does_not_cancel_a_newer_run(scheduler, robot):
    async def body():
        await co.park()

    cmd = Command.no_requirements(body).named("Reused")
    robot.robot_mode = RobotMode.TELEOPERATED
    scheduler.schedule(cmd)
    scheduler.run()
    scheduler.cancel(cmd)

    robot.robot_mode = RobotMode.AUTONOMOUS
    scheduler.schedule(cmd)
    scheduler.run()
    assert scheduler.is_running(cmd), "the old teleop binding must not cancel the auto run"
    scheduler.run()
    assert scheduler.is_running(cmd)


def test_stale_binding_still_cancels_its_own_run(scheduler, robot):
    async def body():
        await co.park()

    cmd = Command.no_requirements(body).named("Teleop only")
    robot.robot_mode = RobotMode.TELEOPERATED
    scheduler.schedule(cmd)
    scheduler.run()
    robot.robot_mode = RobotMode.AUTONOMOUS
    scheduler.run()
    assert not scheduler.is_running(cmd)


def test_finished_bindings_are_pruned(scheduler):
    one_shot = Command.no_requirements(lambda: None).named("One shot")
    for _ in range(50):
        scheduler.schedule(one_shot)
        scheduler.run()
    scheduler.run()
    assert len(scheduler._active_bindings) == 0


def test_default_command_bindings_are_not_duplicated(scheduler):
    mechanism = DummyMechanism("mechanism", scheduler)
    default_cmd = mechanism.run(lambda: None).named("Default")  # finishes immediately
    mechanism.set_default_command(default_cmd)
    for _ in range(50):
        scheduler.run()
    assert len(scheduler._active_bindings) <= 1
